    "questionAr": "إذا كانت درجة الإذابة المولارية ($S$) لملح شحيح الذوبان هيدروكسيد الألومنيوم في الماء عند $25^\\circ\\text{C}$ هي $S = 1.0e-08\\text{ mol/L}$. احسب حاصل الإذابة ($K_{sp}$) لهذا الملح.",
