    "questionAr": "في مسألة الاتزان المتقدمة: Equal amounts ($2.0\\text{ mol}$ each) of $\\text{CO}$ and $\\text{H}_2\\text{O}$ are placed in a $1.0\\text{ L}$ flask. If $K_c = 9.0$, calculate the equilibrium concentration of $\\text{CO}_2$.",
