    "stepByStepSolutionEn": [
      "Let $x = [\\text{CO}_2] = [\\text{H}_2]$. Then $[\\text{CO}] = [\\text{H}_2\\text{O}] = 2 - x$. $K_c = \\frac{x^2}{(2-x)^2} = 9.0 \\implies \\frac{x}{2-x} = 3 \\implies x = 6 - 3x \\implies 4x = 6 \\implies x = 1.5\\text{ M}$."
    ],
